public String format(LoggingEvent event) {
        StringBuilder formatBuf = new StringBuilder(256);
        int i = 0;
        int len = pattern.length();
        char c;
        boolean beginFormat = false;
        while (i < len) {
            c = pattern.charAt(i);
            if (!beginFormat) {
                if (c == '%') {
                    beginFormat = true;
                } else {
                    formatBuf.append(c);
                }
            } else {
                // support up to one optional min-width or precision specifier
                int minLenOrPrec = -1;
                if (c >= '0') {
                    int n = c - '0';
                    if (n == 0) {
                        minLenOrPrec = 0;
                    }
                    // if there really is one treat it as a number
                    while ((i + 1) < len) {
                        c = pattern.charAt(i + 1);
                        if (c < '0') {
                            break;
                        }
                        n = n * 10 + (c - '0');
                        i++;
                    }
                    minLenOrPrec = n;
                }
                // reset to default style if 'xxx'd
                // do not check for '%' flag
                beginFormat = false;
                formatBuf.append(formatForEvent(event, c, minLenOrPrec));
            }
            i++;
        }
        return formatBuf.toString();
    }

