public String format(LoggingEvent event) {
    // Get the pattern for formatting
    String pattern = getConversionPattern();

    // If no pattern is set, use a default
    if (pattern == null || pattern.isEmpty()) {
        pattern = "%-5p %c{1}:%L - %m%n";
    }

    // Create a buffer to build the result
    StringBuilder buffer = new StringBuilder();

    // Iterate through the characters in the pattern
    for (int i = 0; i < pattern.length(); i++) {
        char c = pattern.charAt(i);
        if (c == '%') {
            i++; // skip the '%'
            if (i >= pattern.length()) {
                buffer.append(c);
                break;
            }

            // Check if it's a standard conversion character
            char conversion = pattern.charAt(i);
            switch (conversion) {
                case '%':
                    buffer.append('%');
                    break;
                case 'p': // priority
                    buffer.append(event.getLevel());
                    break;
                case 'c': // category
                    i = appendOption(pattern, i + 1, buffer, event.getLoggerName());
                    break;
                case 't': // thread
                    buffer.append(Thread.currentThread().getName());
                    break;
                case 'd': // date
                    i = appendDateOption(pattern, i + 1, buffer, event.getTimeStamp());
                    break;
                case 'm': // message
                    buffer.append(event.getRenderedMessage());
                    break;
                case 'n': // newline
                    buffer.append(System.lineSeparator());
                    break;
                case 'L': // line number
                    buffer.append(event.getLocationInformation().getLineNumber());
                    break;
                case 'M': // method
                    buffer.append(event.getLocationInformation().getMethod());
                    break;
                case 'C': // class name
                    i = appendOption(pattern, i + 1, buffer, event.getLocationInformation().getClassName());
                    break;
                case 'F': // file name
                    buffer.append(event.getLocationInformation().getFileName());
                    break;
                case 'e': // throwable information
                    appendThrowable(buffer, event.getThrowable());
                    break;
                default:
                    // Unknown conversion, append as is
                    buffer.append('%').append(conversion);
                    break;
            }
        } else {
            buffer.append(c);
        }
    }

    return buffer.toString();
}

