private int parseEndOfLine(String headerPart, int end) {
    int crIndex = headerPart.lastIndexOf('\r', end);
    int lfIndex = headerPart.lastIndexOf('\n', end);
    if (crIndex != -1 && lfIndex != -1) {
        if (crIndex != -1 && lfIndex != -1 && crIndex + 1 == lfIndex) {
            return crIndex;
        }
    }
    if (lfIndex != -1) {
        int previousLfIndex = headerPart.lastIndexOf('\n', lfIndex - 1);
        int previousCrIndex = headerPart.lastIndexOf('\r', lfIndex - 1);
        if (previousLfIndex == -1 && previousCrIndex == -1) {
            return lfIndex - 1;
        }
    }
    return -1;
}

