    resultMap.clear();

    // Create vertices for left partition
    Map<String, V> leftVertices = new HashMap<>();
    for (int i = 0; i < leftSize; i++) {
        String vertexId = "L" + i;
        V vertex = target.addVertex(vertexId);
        leftVertices.put(vertexId, vertex);
        resultMap.put(vertexId, vertex);
    }

    // Create vertices for right partition
    Map<String, V> rightVertices = new HashMap<>();
    for (int i = 0; i < rightSize; i++) {
        String vertexId = "R" + i;
        V vertex = target.addVertex(vertexId);
        rightVertices.put(vertexId, vertex);
        resultMap.put(vertexId, vertex);
    }

    // Connect every vertex in left partition to every vertex in right partition
    for (V leftVertex : leftVertices.values()) {
        for (V rightVertex : rightVertices.values()) {
            if (!target.containsEdge(leftVertex, rightVertex)) {
                target.addEdge(leftVertex, rightVertex);
            }
        }
    }
}

