public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.writeTo(out, message, buffer);
    SchemaEncoder.encoderSizeHeader(size).writeTo(out);
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] serialized;
    if (message == null) {
        serialized = new byte[0];
    } else {
        serialized = schema.serializeToByteArray(message, buffer);
    }
    out.write(CodedOutputStream.computeUInt32SizeNoTag(serialized.length));
    out.write(serialized.length & 0xFF);
    out.write(serialized);
    return serialized.length;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    ByteBuffer byteBuffer = LinkedBuffer.allocate(4096);
    byte[] bytes = schema.encode(message, buffer);
    byteBuffer.putInt(bytes.length);
    byteBuffer.put(bytes);
    byteBuffer.flip();
    while (byteBuffer.hasRemaining()) {
        out.write(byteBuffer.get());
    }
    return bytes.length;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = (int) writeDelimitedTo(out, message, schema, buffer);
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getMessageSize(message);
    CodedOutputStream.writeSize(size, out);
    schema.serialize(message, out, buffer);
    return size;
}

