protected void subAppend(LoggingEvent event) {
    // Ensure that the event has a message and that the message is not null
    if (event.getMessage() == null) {
        return;
    }

    // Convert the logging event to a string for processing
    String message = event.getMessage().toString();
    if (message == null) {
        return;
    }

    // Check if the message is empty
    if (message.length() == 0) {
        return;
    }

    // Encode the message using the encoder
    try {
        Encoder encoder = getEncoder();
        if (encoder != null) {
            // Write the encoded data to the output stream
            ByteArrayOutputStream byteStream = new ByteArrayOutputStream();
            encoder.encode(message, byteStream);
            getLocation().write(byteStream.toByteArray());
        }
    } catch (Exception e) {
        handleException(new IOException("Failed to write event: " + e.getMessage()), e);
    }

    // Force flush to ensure the data is written
    forceFlush();
}

