public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
        if (!(genericType instanceof ParameterizedType)) {
            return null;
        }
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];
        for (int i = 0; i < typeArguments.length; i++) {
            Type typeArgument = typeArguments[i];
            if (typeArgument instanceof Class) {
                resolvedArguments[i] = (Class<?>) typeArgument;
            } else if (typeArgument instanceof ParameterizedType) {
                ParameterizedType nestedParamType = (ParameterizedType) typeArgument;
                Class<?> rawType = (Class<?>) nestedParamType.getRawType();
                if (targetType != null && targetType.isAssignableFrom(rawType)) {
                    resolvedArguments[i] = rawType;
                } else {
                    resolvedArguments[i] = rawType;
                }
            } else if (typeArgument instanceof WildcardType) {
                WildcardType wildcardType = (WildcardType) typeArgument;
                Type[] upperBounds = wildcardType.getUpperBounds();
                if (upperBounds.length == 1 && upperBounds[0] instanceof Class) {
                    resolvedArguments[i] = (Class<?>) upperBounds[0];
                } else {
                    resolvedArguments[i] = Object.class;
                }
            } else {
                resolvedArguments[i] = Object.class;
            }
        }
        return resolvedArguments;
    }

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] typeArguments = parameterizedType.getActualTypeArguments();
    Class<?>[] resolved = new Class<?>[typeArguments.length];
    for (int i = 0; i < typeArguments.length; i++) {
        Type typeArgument = typeArguments[i];
        if (typeArgument instanceof Class) {
            resolved[i] = (Class<?>) typeArgument;
        } else if (typeArgument instanceof WildcardType) {
            WildcardType wildcardType = (WildcardType) typeArgument;
            Type[] upperBounds = wildcardType.getUpperBounds();
            if (upperBounds.length > 0 && upperBounds[0] instanceof Class) {
                resolved[i] = (Class<?>) upperBounds[0];
            } else {
                resolved[i] = Object.class;
            }
        } else if (typeArgument instanceof ParameterizedType) {
            Type rawType = ((ParameterizedType) typeArgument).getRawType();
            if (rawType instanceof Class) {
                resolved[i] = (Class<?>) rawType;
            } else {
                resolved[i] = null;
                break;
            }
        } else {
            return null;
        }
    }
    return resolved;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] typeArguments = parameterizedType.getActualTypeArguments();
    TypeVariable<?>[] typeVariables = parameterizedType.getRawType() instanceof Class
            ? ((Class<?>) parameterizedType.getRawType()).getTypeParameters()
            : null;

    TypeVariable<?>[] targetVariables = targetType.getTypeParameters();
    if (typeArguments.length != typeVariables.length || targetVariables.length != typeArguments.length) {
        return null;
    }

    Class<?>[] result = new Class<?>[typeArguments.length];
    for (int i = 0; i < typeArguments.length; i++) {
        Type arg = typeArguments[i];
        if (arg instanceof Class) {
            result[i] = (Class<?>) arg;
        } else if (arg instanceof TypeVariable) {
            String variableName = ((TypeVariable<?>) arg).getName();
            int index = -1;
            for (int j = 0; j < targetVariables.length; j++) {
                if (targetVariables[j].getName().equals(variableName)) {
                    index = j;
                    break;
                }
            }
            if (index == -1) {
                return null;
            }
            result[i] = Object.class;
        } else if (arg instanceof WildcardType) {
            result[i] = Object.class;
        } else if (arg instanceof ParameterizedType) {
            result[i] = (Class<?>) ((ParameterizedType) arg).getRawType();
        } else {
            return null;
        }
    }
    return result;
}

