public Mappings diffStructure(String tableName, Mappings mappings) {
    Mappings currentMappings = indicesOperations.getMappings(tableName);
    if (currentMappings == null) {
        return mappings;
    }
    Mappings diff = new Mappings();
    // Compare field-level mappings
    if (mappings.getMultipleIndices() != null && !mappings.getMultipleIndices().isEmpty()) {
        for (Map.Entry<String, Mapping> entry : mappings.getMultipleIndices().entrySet()) {
            String indexName = entry.getKey();
            Mapping mapping = entry.getValue();
            if (!currentMappings.getMultipleIndices().containsKey(indexName) ||
                !currentMappings.getMultipleIndices().get(indexName).getFields().equals(mapping.getFields())) {
                diff.addMultipleIndex(indexName, mapping);
            }
        }
    }
    // Compare single-index mapping
    if (mappings.getSingleIndex() != null) {
        if (currentMappings.getSingleIndex() == null ||
            !currentMappings.getSingleIndex().getFields().equals(mappings.getSingleIndex().getFields())) {
            diff.setSingleIndex(mappings.getSingleIndex());
        }
    }
    return diff;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    Mappings historyMappings = indexManagementClient.getHistoryMappings(tableName);
    if (historyMappings == null) {
        return new Mappings();
    }
    Mappings diff = new Mappings();
    Map<String, Mappings.Property> currentProperties = mappings.getProperties();
    Map<String, Mappings.Property> historyProperties = historyMappings.getProperties();
    if (currentProperties != null) {
        for (Map.Entry<String, Mappings.Property> entry : currentProperties.entrySet()) {
            String fieldName = entry.getKey();
            if (!historyProperties.containsKey(fieldName)) {
                diff.addProperty(fieldName, entry.getValue());
            }
        }
    }
    // Remove _source to avoid conflicts with current index updates
    diff.removeSourceConfig();
    return diff;
}

