static long compressTimeBucket(long timeBucket, int dayStep) {
        // Extract year (first 4 digits), month (next 2), day (last 2)
        long year = timeBucket / 10000;
        long month = (timeBucket % 10000) / 100;
        long day = timeBucket % 100;

        // Determine the start of the current step period
        // The step periods are: 1st, 12th, 23rd, etc. (i.e., 1 + (n-1)*dayStep for n >= 1, but let's think differently)
        // Actually, looking at the example: dayStep=11
        // 20000105 -> 20000101 (day 5 falls in period starting day 1)
        // 20000115 -> 20000112 (day 15 falls in period starting day 12)
        // 20000123 -> 20000123 (day 23 falls in period starting day 23)
        // So the period starts are: 1, 12, 23, ... which is 1 + (n-1)*11 for n=1,2,3,...
        // For a given day, we need to find the largest start value <= day where start = 1 + k*dayStep for some k >= 0
        // So: start = 1 + k*dayStep, where k = floor((day-1)/dayStep)
        int k = (int)((day - 1) / dayStep);
        long startDay = 1 + (long)k * dayStep;

        // Build the new time bucket with the start day
        long newTimeBucket = year * 10000 + month * 100 + startDay;
        return newTimeBucket;
    }

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket == 0 || dayStep <= 0) {
        return timeBucket;
    }
    long year = timeBucket / 10000;
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Get the first day of the month
    long firstDayOfMonth = year * 10000 + month * 100 + 1;

    // Calculate the offset from the start of the month
    int offset = day - 1;

    // Determine the bucket index
    int bucketNum = offset / dayStep;

    // The start day of this bucket
    int bucketStartDay = bucketNum * dayStep + 1;

    return year * 10000 + month * 100 + bucketStartDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
        if (dayStep <= 0) {
            throw new IllegalArgumentException("dayStep must be positive");
        }
        String str = Long.toString(timeBucket);
        // Extract year, month, day
        int year = Integer.parseInt(str.substring(0, 4));
        int month = Integer.parseInt(str.substring(4, 6));
        int day = Integer.parseInt(str.substring(6, 8));

        // Calculate which day of the month for bucketing
        int targetDay = ((day - 1) / dayStep) * dayStep + 1;

        return (long) year * 10000 + (long) month * 100 + targetDay;
    }

static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the number of days from the start of the year to the given date
    int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) {
        daysInMonth[1] = 29;
    }

    int totalDays = day - 1;
    for (int m = 1; m < month; m++) {
        totalDays += daysInMonth[m - 1];
    }

    // Calculate the bucket index (0-based)
    int bucketIndex = totalDays / dayStep;
    // Calculate the start day of the bucket (0-based, then +1 for 1-based day)
    int startDayInYear = bucketIndex * dayStep + 1;

    // Convert back to month and day
    int currentMonth = 1;
    int currentDay = startDayInYear;
    while (currentMonth <= 12) {
        if (currentDay <= daysInMonth[currentMonth - 1]) {
            break;
        }
        currentDay -= daysInMonth[currentMonth - 1];
        currentMonth++;
    }

    return year * 10000 + currentMonth * 100 + currentDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Convert to a serial day number for easier arithmetic
    // We can use a simple approach: convert to a date, but since we don't have Calendar/JDK easily in scope (though it's JDK), 
    // let's just compute the step relative to the day.
    // Actually, the simplest and most robust way given the examples is to just adjust the day part.
    // Examples: dayStep = 11
    // 20000105 -> 20080101 (wait, 2000-01-05 -> 2000-01-01, diff is 4, so previous multiple of 11 including 1? 
    // 20000115 -> 20000112, diff is 3. 
    // 20000123 -> 20000123, diff is 0.
    // It seems like we're finding the latest date that is a multiple of dayStep (where day 1 is the anchor, i.e., day mod dayStep == 1) 
    // or something similar. But 12 % 11 = 1, so day 12 is the second multiple (1, 12, 23). 
    // So for dayStep 11, the days are 1, 12, 23.
    // For day 5: 1 is the latest multiple (1 <= 5).
    // For day 15: 12 is the latest multiple (12 <= 15).
    // For day 23: 23 is the latest multiple (23 <= 23).

    // So the formula is: bucketDay = ((day - 1) / dayStep) * dayStep + 1
    // Let's check: day=5 -> (4/11)*11 + 1 = 0*11+1 = 1. Correct.
    // day=15 -> (14/11)*11 + 1 = 1*11+1 = 12. Correct.
    // day=23 -> (22/11)*11 + 1 = 2*11+1 = 23. Correct.

    int bucketDay = ((day - 1) / dayStep) * dayStep + 1;

    return year * 10000 + month * 100 + bucketDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = 0; i < len; i++) {
        int cp = str.charAt(index + i);
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (Character.isSurrogate(cp)) {
            if (i < len - 1) {
                int nextCp = str.charAt(index + i + 1);
                if (Character.isTrailSurrogate(nextCp)) {
                    size += 4;
                    i++;
                } else {
                    size += 3;
                }
            } else {
                size += 3;
            }
        } else {
            size += 3;
        }
    }
    return size;
}

