        int size = 0;
        for (int i = index; i < index + len; i++) {
            char c = str.charAt(i);
            if (c < 0x80) {
                size += 1;
            } else if (c < 0x800) {
                size += 2;
            } else {
                size += 3;
            }
        }
        return size;
    }

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("string must not be null");
    }

    int start = index;
    int end = index + len;
    if (start < 0 || end > str.length() || start > end) {
        throw new IndexOutOfBoundsException("Invalid index/length: " + start + ", " + len);
    }

    int utf8Size = 0;
    for (int i = start; i < end; i++) {
        int codePoint = str.charAt(i);
        if (codePoint < 0x80) {
            utf8Size += 1;
        } else if (codePoint < 0x800) {
            utf8Size += 2;
        } else if (codePoint < 0x10000) {
            utf8Size += 3;
        } else {
            utf8Size += 4;
        }
    }

    return utf8Size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(index + i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            size += 4;
            // This is a surrogate pair, consume the next char if it's a low surrogate
            if (i + 1 < len && Character.isLowSurrogate(str.charAt(index + i + 1))) {
                i++;
            } else {
                // Invalid surrogate, count it as 3 bytes for the high surrogate alone (CEFF)
                size -= 1; // Adjust to 3 if no corresponding low surrogate
            }
        } else {
            // Includes low surrogate alone and characters 0x800 to 0xFFFF
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len && i < str.length(); i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size += 1;
        } else if (c < 0x800) {
            // Handle surrogate pairs for characters above 0xFFFF
            if (Character.isHighSurrogate(c) && i + 1 < index + len && i + 1 < str.length()) {
                char next = str.charAt(i + 1);
                if (Character.isLowSurrogate(next)) {
                    size += 4;
                    i++; // Skip the low surrogate
                    continue;
                }
            }
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            if (i + 1 < index + len && i + 1 < str.length()) {
                char next = str.charAt(i + 1);
                if (Character.isLowSurrogate(next)) {
                    size += 4;
                    i++; // Skip the low surrogate
                    continue;
                }
            }
            size += 3;
        } else {
            size += 3;
        }
    }
    return size;
}

