public boolean remove(int val) {
        if (hashMap.containsKey(val)) {
            List<Integer> list = hashMap.get(val);
            int lastVal = list.remove(list.size() - 1);
            if (lastVal != val) {
                int index = indexMap.get(lastVal);
                list.set(index, val);
                indexMap.put(val, index);
            }
            if (list.isEmpty()) {
                hashMap.remove(val);
            } else {
                hashMap.put(val, list);
            }
            indexMap.remove(val);
            hashMap.remove(lastVal);
            return true;
        }
        return false;
    }

