    }

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("Byte length cannot be negative: " + byteLength);
    }
    if (byteLength == 0) {
        return this;
    }
    if (bytes == null) {
        bytes = new byte[byteLength];
    } else if (size + byteLength > bytes.length) {
        bytes = Arrays.copyOf(bytes, size + byteLength);
    }
    if (byteArrayValue == null) {
        Arrays.fill(bytes, size, size + byteLength, (byte) 0);
    } else {
        if (byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new IllegalArgumentException("Invalid byte offset or length");
        }
        System.arraycopy(byteArrayValue, byteOffset, bytes, size, byteLength);
    }
    size += byteLength;
    return this;
}

