public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || str.length() == 0) {
        return lb;
    }

    final int len = str.length();
    final byte[] utf8Bytes = str.toString().getBytes(Charset.forName("UTF-8"));

    if (utf8Bytes == null || utf8Bytes.length == 0) {
        return lb;
    }

    final int available = lb.writeSpace();

    if (available < utf8Bytes.length) {
        if (session == null) {
            throw new IllegalArgumentException("Session must not be null when buffer write space is insufficient");
        }
        // Extend the buffer
        final int requiredCapacity = available < utf8Bytes.length ? utf8Bytes.length : utf8Bytes.length - available;
        session.extendBuffer(requiredCapacity);
    }

    if (lb.writeSpace() >= utf8Bytes.length) {
        lb.writeBytes(utf8Bytes, 0, utf8Bytes.length);
    } else {
        throw new IllegalArgumentException("Insufficient write space in LinkedBuffer after extension");
    }

    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }
    final byte[] buffer = new byte[str.length() * 3];
    int offset = 0;
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            if (offset == buffer.length) {
                return lb;
            }
            buffer[offset++] = (byte) c;
        } else if (c < 0x800) {
            if (offset + 2 >= buffer.length) {
                return lb;
            }
            buffer[offset++] = (byte) (0xC0 | (c >> 6));
            buffer[offset++] = (byte) (0x80 | (c & 0x3F));
        } else if (c < 0xD800 || c > 0xDFFF) {
            if (offset + 3 >= buffer.length) {
                return lb;
            }
            buffer[offset++] = (byte) (0xE0 | (c >> 12));
            buffer[offset++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            buffer[offset++] = (byte) (0x80 | (c & 0x3F));
        } else {
            // surrogate pair
            if (i + 1 >= str.length()) {
                return lb;
            }
            char low = str.charAt(++i);
            int codePoint = 0x10000 + ((c - 0xD800) << 10) + (low - 0xDC00);
            if (offset + 4 >= buffer.length) {
                return lb;
            }
            buffer[offset++] = (byte) (0xF0 | (codePoint >> 18));
            buffer[offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
            buffer[offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
            buffer[offset++] = (byte) (0x80 | (codePoint & 0x3F));
        }
    }
    session.writeBytes(buffer, 0, offset);
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
        final byte[] bytes = str.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
        final int length = bytes.length;
        if (length > 0) {
            // Ensure there is enough space in the current buffer, if not, allocate new
            while (session.writableBytes() < length) {
                session.allocate();
            }
            final byte[] buffer = session.byteBuffer();
            System.arraycopy(bytes, 0, buffer, buffer.length - session.writableBytes() - length, length);
            session.writerIndex(length);
            session.appendBuffer(lb);
        }
        return lb;
    }

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
        int len = str.length();
        int blockCapacity = lb.blockCapacity();
        int headerSize = lb.headerSize();

        int start = session.startIndex();
        int end = start + len;
        int overflow = Math.max(end - blockCapacity, 0);

        if (overflow > 0) {
            String chunk = str.subSequence(0, len - overflow).toString();
            lb = writeUTF8(chunk, session, lb);
            session.setPosition(lb.writeIndex());
            return writeUTF8(str.subSequence(len - overflow, len), session, lb);
        }

        return writeUTF8Chunk(str, session, lb);
    }

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    lb.reserveLast(0);
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            session.write(c);
        } else if (c < 0x800) {
            session.write((0xC0 | (c >> 6)));
            session.write((0x80 | (c & 0x3F)));
        } else if (Character.isHighSurrogate(c)) {
            int i1 = i + 1;
            if (i1 < len) {
                char c1 = str.charAt(i1);
                if (Character.isLowSurrogate(c1)) {
                    int cp = Character.toCodePoint(c, c1);
                    session.write((0xF0 | (cp >> 18)));
                    session.write((0x80 | ((cp >> 12) & 0x3F)));
                    session.write((0x80 | ((cp >> 6) & 0x3F)));
                    session.write((0x80 | (cp & 0x3F)));
                    i = i1;
                } else {
                    session.write(0xEF);
                    session.write(0xBF);
                    session.write(0xBD);
                }
            } else {
                session.write(0xEF);
                session.write(0xBF);
                session.write(0xBD);
            }
        } else if (Character.isLowSurrogate(c)) {
            session.write(0xEF);
            session.write(0xBF);
            session.write(0xBD);
        } else {
            session.write((0xE0 | (c >> 12)));
            session.write((0x80 | ((c >> 6) & 0x3F)));
            session.write((0x80 | (c & 0x3F)));
        }
    }
    return lb.writeLast();
}

