public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<PathSegmentImpl>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    if (path.isEmpty()) {
        return segments;
    }
    String[] parts = path.split("/", -1);
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String segment;
        if (decode) {
            segment = URLDecoder.decode(part, "UTF-8");
        } else {
            segment = part;
        }
        segments.add(new PathSegmentImpl(segment, decode));
    }
    return segments;
}

