            return Collections.emptyList();
        }
        List<String> segments = new ArrayList<>();
        int start = 0;
        for (int i = 0; i < path.length(); i++) {
            if (path.charAt(i) == '/') {
                if (i > start) {
                    segments.add(path.substring(start, i));
                }
                start = i + 1;
            }
        }
        if (start < path.length()) {
            segments.add(path.substring(start));
        }
        List<PathSegmentImpl> result = new ArrayList<>();
        for (String segment : segments) {
            PathSegmentImpl impl = new PathSegmentImpl(segment);
            if (decode) {
                impl = new PathSegmentImpl(decodeURIComponent(segment));
            }
            result.add(impl);
        }
        return result;
    }

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    if (path.isEmpty()) {
        return segments;
    }
    String[] parts = path.split("/", -1);
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        if (decode) {
            part = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8);
        }
        segments.add(new PathSegmentImpl(part));
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<PathSegmentImpl>();
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    if (path.isEmpty()) {
        return segments;
    }
    String[] parts = path.split("/", -1);
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        if (decode) {
            try {
                part = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(part));
    }
    return segments;
}

