public Converter lookup(final Class<?> clazz) {
    if (clazz == null) {
        return null;
    }
    Converter converter = converters.get(clazz);
    if (converter != null) {
        return converter;
    }
    // If no direct converter found, look for a converter that can convert to the superclass
    for (Class<?> classToCheck = clazz; classToCheck != null; classToCheck = classToCheck.getSuperclass()) {
        converter = converters.get(classToCheck);
        if (converter != null) {
            return converter;
        }
    }
    // Check interfaces
    for (Class<?> interfaceClass : clazz.getInterfaces()) {
        converter = lookup(interfaceClass);
        if (converter != null) {
            return converter;
        }
    }
    return null;
}

public long readRawVarint64() throws IOException {
        int shift = 0;
        long result = 0;
        while (shift < 64) {
            int b = readRawByte();
            if (b == -1) {
                throw new IOException("Unexpected end of stream");
            }
            if ((b & 0x80) == 0) {
                result |= ((long) b) << shift;
                return result;
            }
            result |= ((long) (b & 0x7F)) << shift;
            shift += 7;
        }
        throw new IOException("Malformed Varint");
    }

public long readRawVarint64() throws IOException {
    int shift = 0;
    long result = 0;
    while (true) {
        int b = read();
        if (b == -1) {
            throw new EOFException("Unexpected end of stream while reading varint");
        }
        result |= (long) (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break;
        }
        shift += 7;
        if (shift >= 64) {
            throw new IllegalStateException("Varint too large");
        }
    }
    return result;
}

