}

public long readRawVarint64() throws IOException {
    int shift = 0;
    long result = 0;
    while (true) {
        byte b = readByte();
        if (b < 0) {
            throw new IOException("Failed to read varint.");
        }
        result |= (long) (b & 0x7F) << shift;
        if (b < 0x80) {
            break;
        }
        shift += 7;
        if (shift >= 64) {
            throw new IOException("Failed to read varint (possible corruption).");
        }
    }
    return result;
}

public long readRawVarint64() throws IOException {
    long result = 0;
    int shift = 0;
    while (shift < 64) {
        int b = readRawByte();
        if (b < 0) {
            throw new IOException("Negative byte");
        }
        if ((b & 0x80) == 0) {
            result |= ((long) b) << shift;
            return result;
        } else {
            result |= ((long) (b & 0x7f)) << shift;
            shift += 7;
        }
    }
    // Note: This shouldn't happen for valid Varints but included for completeness
    throw new IOException("Malformed Varint64");
}

