private void pop(final String descriptor) {
        final int start = descriptor.indexOf('(');
        if (start == -1) {
            // It's a type descriptor, pop one frame
            outputFrameStack.pop();
            return;
        }

        final int end = descriptor.indexOf(')', start + 1);
        if (end == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }

        // Parse the argument types between '(' and ')'
        final String args = descriptor.substring(start + 1, end);
        int index = 0;
        while (index < args.length()) {
            final char c = args.charAt(index);
            switch (c) {
                case 'B': // byte
                case 'C': // char
                case 'D': // double
                case 'F': // float
                case 'I': // int
                case 'J': // long
                case 'S': // short
                case 'Z': // boolean
                    // These are each one frame
                    outputFrameStack.pop();
                    index++;
                    break;
                case 'L': // reference type
                    // Find the semicolon
                    final int semicolon = args.indexOf(';', index);
                    if (semicolon == -1) {
                        throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
                    }
                    outputFrameStack.pop();
                    index = semicolon + 1;
                    break;
                case '[': // array
                    // Just skip the '[' and process the next type descriptor
                    outputFrameStack.pop();
                    index++;
                    break;
                default:
                    throw new IllegalArgumentException("Unexpected character in method descriptor: " + c);
            }
        }
    }

private void pop(final String descriptor) {
    int numTypes = 0;
    int i = 0;
    if (descriptor.charAt(0) == '(') {
        i++;
        while (descriptor.charAt(i) != ')') {
            if (descriptor.charAt(i) == '[') {
                i++;
                continue;
            }
            char ch = descriptor.charAt(i);
            if (ch == 'V' || ch == 'Z' || ch == 'B' || ch == 'S' || ch == 'C' || ch == 'I' || ch == 'J' || ch == 'F' || ch == 'D') {
                numTypes++;
            } else if (ch == 'L') {
                numTypes++;
            } else if (ch == '[') {
                // handled above
            } else {
                // should not happen
            }
            i++;
        }
        i++; // skip ')'
        numTypes++; // return type
    } else {
        numTypes = countParameters(descriptor);
    }
    while (numTypes > 0) {
        outputFrame.pop();
        numTypes--;
    }
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    final int len = descriptor.length();
    int index = 0;
    while (index < len) {
        final char c = descriptor.charAt(index);
        switch (c) {
            case 'C':
            case 'F':
            case 'S':
            case 'I':
            case 'B':
            case 'J':
            case 'Z':
            case 'V':
                index++;
                popOne();
                break;
            case 'D':
                index++;
                popTwo();
                break;
            case 'L':
                index = skipUntil(';', index + 1) + 1;
                popOne();
                break;
            case '[':
                index++;
                break;
            case '(':
                index = skipUntil(')', index + 1);
                break;
            case ')':
                index++;
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor character: " + c);
        }
    }
}

private void pop(final String descriptor) {
    String typeDescriptor = descriptor;
    int depth = 0;
    int i = 0;
    if (descriptor.charAt(0) == '(') {
        // Method descriptor: skip the argument types
        i = 1;
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            i = skipType(descriptor, i);
        }
        // At the closing paren ')'
    } else {
        // Type descriptor: just the return type
    }
    int j = i;
    if (descriptor.charAt(j) == '(') {
        // Skip the closing paren
        j = i + 1;
        // Now skip the return type (or void)
    }
    // Pop argument types in reverse order
    i = 1; // start after '(' if method descriptor
    if (descriptor.charAt(0) == '(') {
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            int next = skipType(descriptor, i);
            popType(descriptor.substring(i, next));
            i = next;
        }
    } else {
        popType(descriptor);
    }
}

private void pop(final String descriptor) {
    if (descriptor.charAt(0) == '[') {
        pop(descriptor.substring(1, descriptor.length()));
    } else if (descriptor.length() == 1) {
        pop(descriptor.charAt(0));
    } else {
        int typeStart = 1;
        int typeEnd = descriptor.length() - 1;
        while (typeEnd > 0 && descriptor.charAt(typeEnd - 1) == ')') {
            typeEnd--;
        }
        if (descriptor.charAt(typeEnd - 1) == '(') {
            String args = substring(descriptor, typeEnd - 1);
            while (!args.isEmpty()) {
                args = substring(args);
            }
        } else {
            pop(descriptor.substring(typeStart, typeEnd));
        }
    }
}

