        }
        if (off < 0 || len < 0 || off + len > b.length) {
            throw new IndexOutOfBoundsException("Specified range does not fit in array");
        }

        // Calculate the current size and the new size
        int currentSize = this.buf.length; // Assuming this is the buffer size or the tracked size
        int newSize = currentSize + len;

        // Check if the buffer has enough space
        if (newSize > this.buf.length) {
            // Grow the buffer if needed
            int minCapacity = Math.max(this.buf.length * 2, newSize);
            byte[] newBuffer = new byte[minCapacity];
            System.arraycopy(this.buf, 0, newBuffer, 0, currentSize);
            this.buf = newBuffer;
        }

        // Write the data to the buffer
        System.arraycopy(b, off, this.buf, currentSize, len);

        // Update the size
        this.size = newSize;
    }

