public static String capitalize(String name){
    if (name == null || name.isEmpty()) {
        return name;
    }
    int length = name.length();
    char[] chars = name.toCharArray();
    for (int i = 0; i < length; i++) {
        if (Character.isUpperCase(chars[i])) {
            if (i == 0) {
                // if the first char is uppercase, all prefix is uppercase
                if (i < length - 1 && Character.isLowerCase(chars[i + 1])) {
                    return Character.toUpperCase(chars[i]) + name.substring(1);
                } else {
                    // convert first to lower, leave the rest
                    return Character.toLowerCase(chars[i]) + name.substring(1);
                }
            } else {
                // find the first non-uppercase letter
                int nextIndex = findNextIndexNotUpperCase(chars, i);
                if (nextIndex == -1) {
                    // if all upper case, convert first to lower
                    return Character.toLowerCase(chars[i]) + name.substring(1);
                }
                // keep the first part as is, and capitalize the next one
                return name.substring(0, i) + Character.toLowerCase(chars[i]) + name.substring(i + 1);
            }
        }
    }
    // no uppercase letters
    return Character.toUpperCase(chars[0]) + name.substring(1);
}

