        int abstractType = currentFrame[i];
        if (abstractType < Opcodes.TOP) {
            // Simple type, use it directly
            putShort(abstractType);
        } else {
            // Abstract type, need to look up the corresponding stack map table entry
            int subtype = abstractType - Opcodes.NEW;
            int stackMapTableEntry = stackMapTableOffsets.get(subtype);
            if (stackMapTableEntry < 0) {
                stackMapTableEntries.add(stackMapTableEntries.size(), abstractType);
                stackMapTableOffsets.put(subtype, stackMapTableEntries.size() - 1);
            }
            putShort(stackMapTableEntry);
        }
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; ++i) {
        int abstractType = currentFrame[i];
        if (abstractType < 0 || abstractType > 65535) {
            throw new IllegalArgumentException("Invalid abstract type: " + abstractType);
        }
        if (abstractType == 0) {
            // TOP
            stackMapTableEntries.addShort(0);
        } else if (abstractType == 1) {
            // INTEGER
            stackMapTableEntries.addShort(1);
        } else if (abstractType == 2) {
            // FLOAT
            stackMapTableEntries.addShort(2);
        } else if (abstractType == 3) {
            // DOUBLE
            stackMapTableEntries.addShort(3);
        } else if (abstractType == 4) {
            // LONG
            stackMapTableEntries.addShort(4);
        } else if (abstractType == 5) {
            // NULL
            stackMapTableEntries.addShort(5);
        } else if (abstractType == 6) {
            // UNINITIALIZED_THIS
            stackMapTableEntries.addShort(6);
        } else if (abstractType <= 127) {
            // CONSTANT_CLASS
            stackMapTableEntries.addShort(abstractType);
        } else {
            // CONSTANT_CLASS
            stackMapTableEntries.addShort(255); // placeholder, adjust as needed
            stackMapTableEntries.addInt(abstractType - 128);
        }
