private static int digitValue(final char c) {
    if (c >= '0' && c <= '9') {
        return c - '0';
    } else if (c >= 'A' && c <= 'Z') {
        return c - 'A' + 10;
    } else if (c >= 'a' && c <= 'z') {
        return c - 'a' + 10;
    } else {
        return -1;
    }
}

private Map<String, Object> buildContent(JsonObject jsonObject) {
    Map<String, Object> content = new HashMap<>();
    if (jsonObject.has("@")) {
        content.put("@", jsonObject.get("@").getAsString());
    }
    JsonObject contentJson = jsonObject.getAsJsonObject("content");
    if (contentJson != null) {
        for (Map.Entry<String, JsonElement> entry : contentJson.entrySet()) {
            content.put(entry.getKey(), entry.getValue().isJsonArray()
                    ? entry.getValue().getAsJsonArray().toString()
                    : entry.getValue().getAsString());
        }
    }
    return content;
}

private Map<String, Object> buildContent(JsonObject jsonObject) {
        Map<String, Object> contentMap = new HashMap<>();
        if (jsonObject == null) {
            return contentMap;
        }

        Iterator<Map.Entry<String, JsonElement>> entries = jsonObject.entrySet().iterator();
        while (entries.hasNext()) {
            Map.Entry<String, JsonElement> entry = entries.next();
            String key = entry.getKey();
            JsonElement value = entry.getValue();

            if (value.isJsonNull()) {
                contentMap.put(key, null);
            } else if (value.isJsonPrimitive()) {
                JsonPrimitive primitive = value.getAsJsonPrimitive();
                if (primitive.isNumber()) {
                    contentMap.put(key, primitive.getAsNumber());
                } else if (primitive.isBoolean()) {
                    contentMap.put(key, primitive.getAsBoolean());
                } else {
                    contentMap.put(key, primitive.getAsString());
                }
            } else if (value.isJsonObject()) {
                contentMap.put(key, buildContent(value.getAsJsonObject()));
            } else if (value.isJsonArray()) {
                List<Object> list = new ArrayList<>();
                JsonArray array = value.getAsJsonArray();
                for (JsonElement element : array) {
                    if (element.isJsonNull()) {
                        list.add(null);
                    } else if (element.isJsonPrimitive()) {
                        JsonPrimitive primitive = element.getAsJsonPrimitive();
                        if (primitive.isNumber()) {
                            list.add(primitive.getAsNumber());
                        } else if (primitive.isBoolean()) {
                            list.add(primitive.getAsBoolean());
                        } else {
                            list.add(primitive.getAsString());
                        }
                    } else if (element.isJsonObject()) {
                        list.add(buildContent(element.getAsJsonObject()));
                    }
                }
                contentMap.put(key, list);
            }
        }

        // If there is an 'ats' field, handle it specifically
        if (jsonObject.has("ats")) {
            JsonElement atsElement = jsonObject.get("ats");
            if (atsElement.isJsonArray()) {
                List<String> atsList = new ArrayList<>();
                for (JsonElement element : atsElement.getAsJsonArray()) {
                    atsList.add(element.getAsString());
                }
                contentMap.put("ats", atsList);
            } else if (atsElement.isJsonPrimitive()) {
                contentMap.put("ats", atsElement.getAsString());
            }
        }

        return contentMap;
    }

