public final byte[] toByteArray() {
    if (buffers.isEmpty()) {
        return new byte[0];
    }

    // Calculate total size
    int totalSize = 0;
    for (java.nio.ByteBuffer buffer : buffers) {
        totalSize += buffer.remaining();
    }

    // Create the resulting byte array
    byte[] result = new byte[totalSize];
    int pos = 0;

    // Copy each buffer's contents
    for (java.nio.ByteBuffer buffer : buffers) {
        int remaining = buffer.remaining();
        buffer.duplicate().get(result, pos, remaining);
        pos += remaining;
    }

    return result;
}

public final byte[] toByteArray() {
    int totalSize = 0;
    for (ByteBuffer buffer : buffers) {
        totalSize += buffer.remaining();
    }
    byte[] result = new byte[totalSize];
    int offset = 0;
    for (ByteBuffer buffer : buffers) {
        int size = buffer.remaining();
        buffer.get(result, offset, size);
        offset += size;
    }
    return result;
}

public final byte[] toByteArray() {
    if (buffer == null) {
        return new byte[0];
    }
    if (buffer.length == 1) {
        byte[] result = new byte[buffer[0].length];
        System.arraycopy(buffer[0], 0, result, 0, buffer[0].length);
        return result;
    } else {
        int totalLength = 0;
        for (byte[] buf : buffer) {
            totalLength += buf.length;
        }
        byte[] result = new byte[totalLength];
        int offset = 0;
        for (byte[] buf : buffer) {
            System.arraycopy(buf, 0, result, offset, buf.length);
            offset += buf.length;
        }
        return result;
    }
}

