public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    final int len = str.length();
    final StringBuilder buf = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i >= (len - 1)) {
                buf.append(ch);
                continue;
            }
            final char nextCh = str.charAt(++i);
            if (nextCh != '/') {
                ch = (char) unescapeJavaChar(nextCh);
            }
        }
        buf.append(ch);
    }
    return buf.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    final int len = str.length();
    if (len == 0) {
        return str;
    }
    final StringBuilder buf = new StringBuilder(len);
    boolean bch = false;
    for (int i = 0; i < len; i++) {
        final char ch = str.charAt(i);
        if (bch) {
            bch = false;
            switch (ch) {
            case 'b':
                buf.append('\b');
                break;
            case 't':
                buf.append('\t');
                break;
            case 'n':
                buf.append('\n');
                break;
            case 'f':
                buf.append('\f');
                break;
            case 'r':
                buf.append('\r');
                break;
            case 'u':
                if (i + 4 < len) {
                    final String s = str.substring(i + 1, i + 5);
                    char ch2 = (char) Integer.parseInt(s, 16);
                    buf.append(ch2);
                    i += 4;
                } else {
                    buf.append(ch);
                }
                break;
            default:
                buf.append(ch);
            }
        } else {
            if (ch == '\\') {
                bch = true;
            } else {
                buf.append(ch);
            }
        }
    }
    if (bch) {
        buf.append('\\');
    }
    return buf.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder buf = new StringBuilder(str.length());
    int i = 0;
    int len = str.length();
    while (i < len) {
        char c = str.charAt(i);
        i++;
        if (c == '\\' && i < len) {
            int codePoint = 0;
            char d = str.charAt(i);
            switch (d) {
                case 't':
                    codePoint = '\t';
                    i++;
                    break;
                case 'b':
                    codePoint = '\b';
                    i++;
                    break;
                case 'n':
                    codePoint = '\n';
                    i++;
                    break;
                case 'r':
                    codePoint = '\r';
                    i++;
                    break;
                case 'f':
                    codePoint = '\f';
                    i++;
                    break;
                case 'u':
                    if (i + 4 > len) {
                        throw new IllegalArgumentException("EOL after \\\\u in unicode escape.");
                    }
                    String u = str.substring(i, i + 4);
                    codePoint = Integer.parseInt(u, 16);
                    i += 4;
                    break;
                case 'x':
                    if (i + 2 > len) {
                        throw new IllegalArgumentException("EOL after \\\\x. Hex char expected.");
                    }
                    codePoint = Integer.parseInt(str.substring(i, i + 2), 16);
                    i += 2;
                    break;
                case '0':
                    codePoint = '\0';
                    i++;
                    break;
                case 'a':
                    codePoint = (char) 7;
                    i++;
                    break;
                case '\\':
                    codePoint = '\\';
                    i++;
                    break;
                case '\'':
                    codePoint = '\'';
                    i++;
                    break;
                case '\"':
                    codePoint = '\"';
                    i++;
                    break;
                default:
                    throw new IllegalArgumentException("Illegal escape character \\\\" + d);
            }
            buf.append((char) codePoint);
        } else {
            buf.append(c);
        }
    }
    return buf.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null || str.length() == 0) {
        return str;
    }
    StringBuilder buf = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i + 1 >= str.length()) {
                throw new Exception("Trailing backslash at end of string: " + str);
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case 'n':
                    buf.append('\n');
                    break;
                case 't':
                    buf.append('\t');
                    break;
                case 'r':
                    buf.append('\r');
                    break;
                case 'f':
                    buf.append('\f');
                    break;
                case 'b':
                    buf.append('\b');
                    break;
                case 'x':
                    if (i + 2 < str.length() || i + 1 < str.length()) {
                        if (i + 1 >= str.length()) {
                            throw new Exception("Invalid hex escape at end of string");
                        }
                        int pos = i + 1;
                        int space = str.length() - pos - 1;
                        if (space >= 2) {
                            String hex = str.substring(pos + 1, pos + 3);
                            try {
                                int ascii = Integer.parseInt(hex, 16);
                                buf.append((char) ascii);
                                i += 2;
                            } catch (NumberFormatException e) {
                                throw new Exception("Invalid hex escape: " + hex);
                            }
                        } else {
                            throw new Exception("Invalid hex escape: too few digits");
                        }
                    } else {
                        throw new Exception("Invalid hex escape");
                    }
                    break;
                case 'u':
                    if (i + 4 < str.length()) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int ascii = Integer.parseInt(hex, 16);
                            buf.append((char) ascii);
                            i += 4;
                        } catch (NumberFormatException e) {
                            throw new Exception("Invalid unicode escape: " + hex);
                        }
                    } else {
                        throw new Exception("Invalid unicode escape: too few digits");
                    }
                    break;
                case '0':
                case '1':
                case '2':
                case '3':
                case '4':
                case '5':
                case '6':
                case '7':
                    int start = i + 1;
                    if (i + 3 < str.length() || i + 2 < str.length()) {
                        int octCount = 0;
                        int pos = start;
                        while (pos < str.length() && pos < start + 3 && str.charAt(pos) >= '0' && str.charAt(pos) <= '7') {
                            pos++;
                            octCount++;
                        }
                        String oct = str.substring(start, start + Math.min(octCount, 3));
                        try {
                            int ascii = Integer.parseInt(oct, 8);
                            buf.append((char) ascii);
                            i = start + octCount - 1;
                        } catch (NumberFormatException e) {
                            throw new Exception("Invalid octal escape: " + oct);
                        }
                    } else {
                        throw new Exception("Invalid octal escape");
                    }
                    break;
                case '\\':
                    buf.append('\\');
                    i++;
                    break;
                case '\'':
                    buf.append('\'');
                    i++;
                    break;
                case '"':
                    buf.append('"');
                    i++;
                    break;
                default:
                    buf.append(ch);
                    break;
            }
        } else {
            buf.append(ch);
        }
    }
    return buf.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    final int len = str.length();
    if (len == 0) {
        return str;
    }
    final StringBuilder buf = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);
        if (ch == '\\' && i < len - 1) {
            i++;
            char ch2 = str.charAt(i);
            switch (ch2) {
                case 'u':
                case 'U':
                    if (i < len - 4) {
                        try {
                            final int codePoint = Integer.parseInt(str.substring(i + 1, i + 5), 16);
                            buf.append((char) codePoint);
                            i += 4;
                        } catch (NumberFormatException ex) {
                            buf.append('\\').append('u');
                        }
                    } else {
                        buf.append('\\').append('u');
                    }
                    break;
                case 'n':
                    buf.append('\n');
                    break;
                case 'r':
                    buf.append('\r');
                    break;
                case 'f':
                    buf.append('\f');
                    break;
                case 'b':
                    buf.append('\b');
                    break;
                case 't':
                    buf.append('\t');
                    break;
                case '"':
                    buf.append('"');
                    break;
                case '\'':
                    buf.append('\'');
                    break;
                case '\\':
                    buf.append('\\');
                    break;
                default:
                    buf.append(ch).append(ch2);
                    break;
            }
        } else {
            buf.append(ch);
        }
    }
    return buf.toString();
}

