final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    final int offset = classFileBuffer.position();
    final int tag = classFileBuffer.getShort(offset) & 0xFFFF;
    if (tag != CONSTANT_Utf8) {
        throw new IllegalArgumentException("Constant pool entry at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8 entry");
    }
    final int length = classFileBuffer.getShort(offset + 2) & 0xFFFF;
    if (length > charBuffer.length) {
        throw new IllegalArgumentException("Buffer is not large enough to hold the UTF-8 string");
    }
    int charPos = 0;
    int bytePos = offset + 4;
    for (int i = 0; i < length; i++) {
        char c = (char) (classFileBuffer.get(bytePos++) & 0xFF);
        charBuffer[charPos++] = c;
    }
    return new String(charBuffer, 0, charPos);
}

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
        int offset = constantPoolOffset + constantPoolEntryIndex * 2;
        int length = ((classFileBuffer[offset] << 8) | classFileBuffer[offset + 1]) & 0xFFFF;
        offset += 2;
        for (int i = 0; i < length; i++) {
            charBuffer[i] = (char) (classFileBuffer[offset + i] & 0xFF);
        }
        return new String(charBuffer, 0, length);
    }

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
        final int length = classFileBuffer.getShort(constantPoolEntryIndex) & 0xFFFF;
        final int offset = classFileBuffer.position() + 3;
        int index = 0;
        while (index < length) {
            int b1 = classFileBuffer.getByte(offset + index) & 0xFF;
            if (b1 < 0x80) {
                charBuffer[index++] = (char) b1;
            } else if (b1 < 0xE0) {
                int b2 = classFileBuffer.getByte(offset + index + 1) & 0xFF;
                charBuffer[index++] = (char) ((b1 << 6) | (b2 & 0x3F)) & 0x7FF;
                index++;
            } else {
                int b2 = classFileBuffer.getByte(offset + index + 1) & 0xFF;
                int b3 = classFileBuffer.getByte(offset + index + 2) & 0xFF;
                charBuffer[index++] = (char) (((b1 << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F)) - 0x10000);
                index += 2;
            }
        }
        classFileBuffer.position(offset + length);
        return new String(charBuffer, 0, length);
    }

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    if (constantPoolEntryIndex < 1 || constantPoolEntryIndex >= constantPoolCount) {
        throw new IllegalArgumentException("Invalid constant pool index: " + constantPoolEntryIndex);
    }

    int inPos = classFileOffset + 8;
    for (int i = 1; i < constantPoolEntryIndex; i++) {
        int tag = classFileBuffer[inPos];
        inPos++;
        switch (tag) {
            case CONSTANT_Utf8:
                inPos += 2 + (classFileBuffer[inPos] & 0xFF) * ((classFileBuffer[inPos + 1] & 0xFF) >> 0);
                break;
            case CONSTANT_Integer:
            case CONSTANT_Float:
                inPos += 4;
                break;
            case CONSTANT_Long:
            case CONSTANT_Double:
                inPos += 8;
                i++;
                break;
            case CONSTANT_Class:
            case CONSTANT_String:
            case CONSTANT_Fieldref:
            case CONSTANT_Methodref:
            case CONSTANT_InterfaceMethodref:
            case CONSTANT_NameAndType:
            case CONSTANT_MethodHandle:
                inPos += 4;
                break;
            case CONSTANT_MethodType:
                inPos += 2;
                break;
            case CONSTANT_InvokeDynamic:
                inPos += 4;
                break;
            case CONSTANT_Module:
            case CONSTANT_Package:
                inPos += 2;
                break;
            default:
                throw new RuntimeException("Invalid constant pool tag: " + tag);
        }
    }

    int tag = classFileBuffer[inPos++];
    if (tag != CONSTANT_Utf8) {
        throw new IllegalArgumentException("Invalid constant pool tag at index " + constantPoolEntryIndex + ": expected Utf8, got " + tag);
    }

    int length = ((classFileBuffer[inPos++] & 0xFF) << 8) | (classFileBuffer[inPos++] & 0xFF);
    for (int i = 0; i < length; i++) {
        charBuffer[i] = (char) (classFileBuffer[inPos++] & 0xFF);
    }

    return new String(charBuffer, 0, length);
}

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
        int index = this.constantPoolEntryIndex * 2 + 12;
        int length = this.classFileBuffer.readUnsignedShort(index + 2);
        classFileBuffer.readChars(charBuffer, 0, length, index + 4);
        return new String(charBuffer, 0, length);
    }

