private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator cir = new OuterFaceCirculator(start, dir);
    Node node = cir.node();
    if (node == stop) {
        return cir;
    }
    while (!predicate.test(node)) {
        cir.next();
        node = cir.node();
        if (node == stop) {
            break;
        }
    }
    return cir;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    Node current = start;
    do {
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current, circulator.getDirection());
        }
        circulator.advance();
        current = circulator.getNode();
    } while (current != stop);
    return new OuterFaceCirculator(stop, circulator.getDirection());
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node current = start;
    do {
        if (predicate.test(current)) {
            return circ;
        }
        circ.advance(dir);
        current = circ.node();
    } while (current != stop);
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node node = circ.node();

    // If the start node is the stop node, return immediately
    if (node == stop) {
        return circ;
    }

    // Traverse the outer face
    do {
        if (predicate.test(node)) {
            return circ;
        }
        circ.advance();
        node = circ.node();
    } while (node != stop);

    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (start == null || stop == null || dir == 0) {
        return null;
    }

    if (predicate.test(start)) {
        return new OuterFaceCirculator(start, dir);
    }

    Node next = getNextEdgeNode(start, dir);
    while (next != nullptr && next != stop) {
        if (predicate.test(next)) {
            return new OuterFaceCirculator(next, dir);
        }
        next = getNextEdgeNode(next, dir);
    }

    // If we reach the stop node or no node found, return circulator to stop
    if (next == nullptr) {
        return null;
    }
    return new OuterFaceCirculator(next, dir);
}

