public void add(LoggingEvent event) {
        if (tail == null) {
            head = event;
            tail = event;
        } else {
            tail.setTimeStamp(event.getTimeStamp());
            tail = event;
        }
        size++;
        if (size > max) {
            size = 0;
        }
    }

public void add(LoggingEvent event) {
    if (event == null) {
        throw new IllegalArgumentException("Event must not be null.");
    }

    int maxLength = this.maxLength;
    if (arms != null && arms.length == maxLength) {
        arms.addFirst(event);
        arms.removeLast();
    } else if (arms.size() < maxLength) {
        if (arms == null) {
            arms = new LinkedList<LoggingEvent>();
        }
        arms.addLast(event);
    }
}

