public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength > 0) {
        if (bytesRemainingInCurrentBuffer() < byteLength) {
            resizeCurrentBuffer(byteLength);
        }
        if (byteArrayValue != null) {
            System.arraycopy(byteArrayValue, byteOffset, byteVector, bucketCount, byteLength);
