public final MatchResult match(CharSequence uri) {
    if (uri == null) {
        return null;
    }
    return match(uri.toString());
}

public final MatchResult match(CharSequence uri) {
    if (uri == null) {
        return null;
    }
    String uriStr = uri.toString();
    if (uriStr.length() == 0) {
        return null;
    }
    if (!uriStr.startsWith("/")) {
        return null;
    }
    String templateStr = this.template.toString();
    if (uriStr.length() < templateStr.length()) {
        return null;
    }
    int uriIndex = 1;
    int templateIndex = 1;
    Map<String, String> pathVariables = new HashMap<>();
    while (uriIndex < uriStr.length() && templateIndex < templateStr.length()) {
        char tChar = templateStr.charAt(templateIndex);
        if (tChar == '{') {
            int endIndex = templateStr.indexOf('}', templateIndex);
            if (endIndex == -1) {
                return null;
            }
            String varName = templateStr.substring(templateIndex + 1, endIndex);
            int nextSlashIndex = uriStr.indexOf('/', uriIndex);
            if (nextSlashIndex == -1) {
                pathVariables.put(varName, uriStr.substring(uriIndex));
                uriIndex = uriStr.length();
                templateIndex = endIndex + 1;
            } else {
                pathVariables.put(varName, uriStr.substring(uriIndex, nextSlashIndex));
                uriIndex = nextSlashIndex;
                templateIndex = endIndex + 1;
            }
        } else if (tChar == '/') {
            if (uriIndex >= uriStr.length() || uriStr.charAt(uriIndex) != '/') {
                return null;
            }
            uriIndex++;
            templateIndex++;
        } else {
            if (uriIndex >= uriStr.length()) {
                return null;
            }
            if (uriStr.charAt(uriIndex) != tChar) {
                return null;
            }
            uriIndex++;
            templateIndex++;
        }
    }
    while (templateIndex < templateStr.length()) {
        if (templateStr.charAt(templateIndex) != '/') {
            return null;
        }
        templateIndex++;
    }
    while (uriIndex < uriStr.length()) {
        if (uriStr.charAt(uriIndex) != '/') {
            return null;
        }
        uriIndex++;
    }
    if (pathVariables.isEmpty()) {
        return new MatchResult(new HashMap<String, String>());
    } else {
        return new MatchResult(pathVariables);
    }
}

public final MatchResult match(CharSequence uri) {
        if (uri == null) {
            throw new NullPointerException("uri cannot be null");
        }
        String uriString = uri.toString();
        String path = uriString;
        int queryIndex = uriString.indexOf('?');
        if (queryIndex >= 0) {
            path = uriString.substring(0, queryIndex);
        }
        int hashIndex = uriString.indexOf('#');
        if (hashIndex >= 0) {
            path = uriString.substring(0, hashIndex);
        }
        // Remove the base path from the URI path if present
        if (basePath != null && path.startsWith(basePath)) {
            path = path.substring(basePath.length());
        }
        if (path.startsWith("/")) {
            path = path.substring(1);
        }
        if (path.endsWith("/")) {
            path = path.substring(0, path.length() - 1);
        }

        String[] segments = path.split("/");
        Map<String, String> parameters = new HashMap<>();

