protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null) {
        return null;
    }
    if (tour.isEmpty()) {
        return new SimpleGraphPath<>(graph, null, null);
    }

    // Use a list of edges to maintain order and track connectivity
    List<E> tourEdges = new ArrayList<>(tour);

    // We'll build a map for quick lookup of edges by their endpoints
    // This is necessary because we don't know the direction of the edges
    Map<V, Set<E>> incidentEdges = new HashMap<>();
    for (V vertex : graph.getVertexSet()) {
        incidentEdges.put(vertex, new HashSet<>(graph.getEdges(vertex)));
    }

    // We need to find a path that uses all edges in the tour
    // This is essentially an Eulerian path problem

    // Start with an arbitrary edge
    V startVertex = null;
    V currentVertex = null;
    E currentEdge = null;

    for (E edge : tour) {
        startVertex = graph.getEdgeSource(edge);
        currentVertex = graph.getEdgeTarget(edge);
        currentEdge = edge;
        break;
    }

    // Build the path
    List<E> pathEdges = new ArrayList<>();
    Set<E> usedEdges = new HashSet<>();

    pathEdges.add(currentEdge);
    usedEdges.add(currentEdge);

    V v1 = startVertex;
    V v2 = currentVertex;

    // Continue building the path until we've used all edges
    while (usedEdges.size() < tour.size()) {
        // Find the next edge from the current vertex
        E nextEdge = null;
        for (E e : incidentEdges.get(v2)) {
            if (tour.contains(e) && !usedEdges.contains(e)) {
                nextEdge = e;
                break;
            }
        }

        if (nextEdge == null) {
            // This shouldn't happen if the graph has an Eulerian path
            throw new IllegalArgumentException("Tour edges do not form a valid path");
        }

        pathEdges.add(nextEdge);
        usedEdges.add(nextEdge);

        // Update the current vertex
        V nextVertex;
        if (graph.getEdgeSource(nextEdge).equals(v2)) {
            nextVertex = graph.getEdgeTarget(nextEdge);
        } else {
            nextVertex = graph.getEdgeSource(nextEdge);
        }

        v1 = v2;
        v2 = nextVertex;
    }

    // Create a GraphPath object from the constructed path
    SimpleGraphPath<V, E> path = new SimpleGraphPath<>(graph, startVertex, v2, pathEdges);

    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (tour.isEmpty()) {
        return null;
    }

    // Create a subgraph containing only the edges in the tour
    Graph<V,E> tourGraph = graph.getSubGraph(null, tour);

    // Find a vertex of odd degree
    V start = null;
    for (V v : tourGraph.getVertices()) {
        if (tourGraph.getDegree(v) % 2 == 1) {
            start = v;
            break;
        }
    }

    // If no vertex of odd degree found, start from any vertex
    if (start == null) {
        start = tourGraph.getVertexIterator().next();
    }

    // Build the tour path
    List<E> tourEdges = new ArrayList<>();
    List<V> pathVertices = new ArrayList<>();

    // Use a depth-first approach to build the path
    Map<V, Deque<E>> adjacency = new HashMap<>();
    for (V v : tourGraph.getVertices()) {
        adjacency.put(v, new ArrayDeque<>());
    }
    for (E e : tourGraph.getEdges()) {
        V v1 = graph.getVertexStub1(e);
        V v2 = graph.getVertexStub2(e);
        adjacency.get(v1).add(e);
        adjacency.get(v2).add(e);
    }

    // Use Hierholzer's algorithm to find the Eulerian path/cycle
    Deque<V> stack = new ArrayDeque<>();
    Deque<V> path = new ArrayDeque<>();
    Set<E> usedEdges = new HashSet<>();

    stack.push(start);
    while (!stack.isEmpty()) {
        V current = stack.peek();
        Iterator<E> it = adjacency.get(current).iterator();
        E nextEdge = null;
        while (it.hasNext()) {
            E e = it.next();
            if (!usedEdges.contains(e)) {
                nextEdge = e;
                break;
            }
        }

        if (nextEdge == null) {
            // No unused edges left, backtrack
            path.push(stack.pop());
        } else {
            usedEdges.add(nextEdge);
            V next = (graph.getVertexStub1(nextEdge).equals(current)) ? graph.getVertexStub2(nextEdge) : graph.getVertexStub1(nextEdge);
            stack.push(next);
        }
    }

    // Build the final path
    for (V v : path) {
        pathVertices.add(v);
    }
    for (int i = 0; i < pathVertices.size() - 1; i++) {
        V v1 = pathVertices.get(i);
        V v2 = pathVertices.get(i + 1);
        E edge = null;
        for (E e : tour) {
            V stub1 = graph.getVertexStub1(e);
            V stub2 = graph.getVertexStub2(e);
            if ((stub1.equals(v1) && stub2.equals(v2)) || (stub1.equals(v2) && stub2.equals(v1))) {
                edge = e;
                break;
            }
        }
        if (edge != null) {
            tourEdges.add(edge);
        }
    }

    return new GraphPath<V,E>() {
        @Override
        public Graph<V, E> getDirectedGraph() {
            return graph;
        }

        @Override
        public Collection<V> getVertices() {
            return pathVertices;
        }

        @Override
        public Collection<E> getEdges() {
            return tourEdges;
        }

        @Override
        public Collection<V> getVerticesInPath(int vertexIndex) {
            List<V> vertices = new ArrayList<>(pathVertices);
            return vertices.subList(vertexIndex, vertices.size());
        }

        @Override
        public Collection<E> getEdgesInPath(int edgeIndex) {
            List<E> edges = new ArrayList<>(tourEdges);
            return edges.subList(edgeIndex, edges.size());
        }

        @Override
        public double getCost() {
            double cost = 0;
            for (E e : tourEdges) {
                cost += graph.getEdgeWeight(e);
            }
            return cost;
        }

        @Override
        public boolean isCyclic() {
            return pathVertices.isEmpty() ? false : pathVertices.get(0).equals(pathVertices.get(pathVertices.size() - 1));
        }
    };
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        List<E> edgeList = new ArrayList<>(tour);
        List<V> nodeList = new ArrayList<>();
        V start = graph.getEdgeSource(edgeList.get(0));
        nodeList.add(start);
        for (E edge : edgeList) {
            V source = graph.getEdgeSource(edge);
            if (!source.equals(start)) {
                start = source;
            }
            V target = graph.getEdgeTarget(edge);
            nodeList.add(target);
        }
        if (nodeList.size() != tour.size() + 1) {
            throw new IllegalStateException("Edge set does not form a valid path");
        }
        return new GraphPath<V, E>(graph, nodeList, new HashSet<>(edgeList));
    }

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Extract the set of vertices
    Set<V> vertices = new HashSet<>();
    for (E edge : tour) {
        VertexPair<V, E> vp = graph.getEdgeEndpoints(edge);
        vertices.add(vp.getSource());
        vertices.add(vp.getTarget());
    }

    // Build an adjacency list for the vertices
    Map<V, NavigableMap<V, E>> adjacency = new HashMap<>();
    for (V vertex : vertices) {
        adjacency.put(vertex, new TreeMap<>(graph.getVertexComparator()));
    }
    for (E edge : tour) {
        VertexPair<V, E> vp = graph.getEdgeEndpoints(edge);
        V source = vp.getSource();
        V target = vp.getTarget();
        if (graph.isDirected()) {
            adjacency.get(source).put(target, edge);
        } else {
            adjacency.get(source).put(target, edge);
            adjacency.get(target).put(source, edge);
        }
    }

    // Start from an arbitrary vertex
    V start = vertices.iterator().next();
    List<V> nodeList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();

    V current = start;
    V currentTarget = null;
    E currentEdge = null;

    int n = tour.size();
    for (int i = 0; i < n; i++) {
        nodeList.add(current);
        NavigableMap<V, E> neighbors = adjacency.get(current);
        // Find the next neighbor (smallest available)
        Map.Entry<V, E> nextEntry = neighbors.firstEntry();
        if (nextEntry == null) {
            break;
        }
        currentTarget = nextEntry.getKey();
        currentEdge = nextEntry.getValue();
        edgeList.add(currentEdge);
        // Remove the used edge from adjacency lists
        adjacency.get(current).remove(currentTarget);
        if (!graph.isDirected()) {
            adjacency.get(currentTarget).remove(current);
        }
        current = currentTarget;
    }

    // Append the last vertex if we have edges, otherwise just start
    if (n > 0) {
        nodeList.add(current);
    }

    GraphPathImpl<V, E> path = new GraphPathImpl<>(start, current, edgeList);
    return path;
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        throw new IllegalArgumentException("Tour must not be null or empty");
    }
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }

    // Build a mapping from vertex to its adjacent edges in the tour
    Map<V, Set<E>> vertexToEdges = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (source != null) {
            vertexToEdges.computeIfAbsent(source, k -> new HashSet<>()).add(edge);
        }
        if (target != null) {
            vertexToEdges.computeIfAbsent(target, k -> new HashSet<>()).add(edge);
        }
    }

    // Start from any vertex with edges
    V startVertex = null;
    for (V vertex : vertexToEdges.keySet()) {
        if (!vertexToEdges.get(vertex).isEmpty()) {
            startVertex = vertex;
            break;
        }
    }
    if (startVertex == null) {
        throw new IllegalArgumentException("No valid start vertex found");
    }

    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    Set<V> visited = new HashSet<>();
    Set<E> usedEdges = new HashSet<>();

    V currentVertex = startVertex;
    visited.add(currentVertex);
    vertices.add(currentVertex);

    // Traverse the tour
    while (usedEdges.size() < tour.size()) {
        List<E> availableEdges = new ArrayList<>(vertexToEdges.get(currentVertex));
        // Remove already used edges
        availableEdges.removeAll(usedEdges);

        if (availableEdges.isEmpty()) {
            throw new IllegalArgumentException("No available edges from vertex " + currentVertex);
        }

        E nextEdge = availableEdges.get(0);
        usedEdges.add(nextEdge);
        edges.add(nextEdge);

        V source = graph.getEdgeSource(nextEdge);
        V target = graph.getEdgeTarget(nextEdge);
        V nextVertex;

        if (source != null && source.equals(currentVertex)) {
            nextVertex = target;
        } else if (target != null && target.equals(currentVertex)) {
            nextVertex = source;
        } else {
            throw new IllegalArgumentException("Edge " + nextEdge + " does not start at vertex " + currentVertex);
        }

        currentVertex = nextVertex;
        if (currentVertex != null && !visited.contains(currentVertex)) {
            visited.add(currentVertex);
        }
        vertices.add(currentVertex);
    }

    // Check if we form a valid tour
    if (vertices.get(0) == null || vertices.get(vertices.size() - 1) == null || !vertices.get(0).equals(vertices.get(vertices.size() - 1))) {
        throw new IllegalArgumentException("The edges do not form a closed tour");
    }

    // Remove the duplicate last vertex (which is the same as the first)
    vertices.remove(vertices.size() - 1);

    return graph.findPathBetween(vertices.get(0), vertices.get(vertices.size() - 1), graph.addAll(Collections.unmodifiableList(edges)));
}

