int addConstantNameAndType(final String name, final String descriptor) {
        final ConstantNameAndType nameAndType = new ConstantNameAndType(name, descriptor);
        if (constantPool.contains(nameAndType)) {
            for (int i = 0; i < constantPool.size(); i++) {
                if (constantPool.get(i).equals(nameAndType)) {
                    return i;
                }
            }
        }
        int index = constantPool.size();
        constantPool.add(nameAndType);
        return index;
    }

int addConstantNameAndType(final String name, final String descriptor) {
        int nameIndex = addConstantUtf8(name);
        int descriptorIndex = addConstantUtf8(descriptor);

        for (Constant<?> c : constants) {
            if (c instanceof CONSTANT_NameAndType_info && ((CONSTANT_NameAndType_info) c).nameIndex == nameIndex
                    && ((CONSTANT_NameAndType_info) c).descriptorIndex == descriptorIndex) {
                return c.index;
            }
        }

        CONSTANT_NameAndType_info nameAndType = new CONSTANT_NameAndType_info(constants.size(), nameIndex, descriptorIndex);
        constants.add(nameAndType);
        return nameAndType.index;
    }

int addConstantNameAndType(final String name, final String descriptor) {
        int nameIndex = addUtf8Constant(name);
        int descriptorIndex = addUtf8Constant(descriptor);
        return addConstantItem("NameAndType", nameIndex, descriptorIndex);
    }

public int addConstantNameAndType(final String name, final String descriptor) {
        String sname = name == null ? "" : name;
        String sdescriptor = descriptor == null ? "" : descriptor;
        for (int i = 0; i < pool.length; i++) {
            Symbol s = pool[i];
            if (s == null) {
                int idx = nextFree();
                Symbol elem = new Symbol(CONSTANT_NameAndType_info, sname, sdescriptor);
                pool[idx] = elem;
                return idx;
            }
            if (s.tag == CONSTANT_NameAndType_info
                    && s.name == sname
                    && s.descriptor == sdescriptor) {
                return i;
            }
        }
        int idx = nextFree();
        Symbol elem = new Symbol(CONSTANT_NameAndType_info, sname, sdescriptor);
        pool[idx] = elem;
        return idx;
    }

public int addConstantNameAndType(final String name, final String descriptor) {
        return addConstant(NameAndType(name, descriptor));
    }

private String unescapeId(String input) {
    if (input == null || input.length() < 2) {
        return input;
    }
    if (input.charAt(0) == '"' && input.charAt(input.length() - 1) == '"') {
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i < input.length() - 1; i++) {
            char c = input.charAt(i);
            if (c == '\\' && i + 1 < input.length() - 1) {
                char next = input.charAt(i + 1);
                if (next == 'n') {
                    sb.append('\n');
                    i++;
                } else if (next == 't') {
                    sb.append('\t');
                    i++;
                } else if (next == '"') {
                    sb.append('"');
                    i++;
                } else if (next == '\\') {
                    sb.append('\\');
                    i++;
                } else {
                    sb.append(c);
                }
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }
    return input;
}

