    Set<Integer> sourceBucket = bucketsByLabel.get(minLabel);
    // Find the new labels by shifting down minLabel to decrease by 1
    for (int newLabel = minLabel; newLabel > 0; newLabel--) {
        Set<Integer> targetBucket = bucketsByLabel.get(newLabel - 1);

        if (newLabel == minLabel) {
            // Move all vertices from the minLabel bucket to bucket 0
            for (int vertex : sourceBucket) {
