public List<SequenceRange> buildSequenceRanges() {
        List<SequenceRange> ranges = new ArrayList<>();
        long minSequence = currentMinSequence;
        long maxSequence = currentMaxSequence;
        if (minSequence > maxSequence) {
            return ranges;
        }

        for (long seq = minSequence; seq <= maxSequence; seq += SEGMENT_SIZE) {
            long segmentEnd = Math.min(seq + SEGMENT_SIZE - 1, maxSequence);
            ranges.add(new SequenceRange(seq, segmentEnd));
        }

        return ranges;
    }

public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> sequenceRanges = new ArrayList<>();
    if (currentProfile != null) {
        List<Long> sequences = currentProfile.getSequences();
        if (sequences != null && !sequences.isEmpty()) {
            Collections.sort(sequences);
            long start = sequences.get(0);
            long end = sequences.get(0);
            for (int i = 1; i < sequences.size(); i++) {
                long seq = sequences.get(i);
                if (seq == end + 1) {
                    end = seq;
                } else {
                    sequenceRanges.add(new SequenceRange(start, end));
                    start = seq;
                    end = seq;
                }
            }
            sequenceRanges.add(new SequenceRange(start, end));
        }
    }
    return sequenceRanges;
}

