        if (path == null || path.length() == 0) {
            return path;
        }
        int extPos = path.lastIndexOf('.');
        if (extPos > -1) {
            int prevExtPos = path.lastIndexOf('/') + 1;
            if (extPos >= prevExtPos) {
                return path.substring(0, extPos);
            }
        }
        int prevDotPos = path.lastIndexOf('.');
        return path.substring(0, prevDotPos);
    }

public static String stripFilenameExtension(String path) {
        if (path == null) {
            return null;
        }
        int extIndex = path.lastIndexOf('.');
        int slashIndex = path.lastIndexOf('/');
        int backslashIndex = path.lastIndexOf('\\');
        int lastDirectorySeparatorIndex = Math.max(
            slashIndex,
            backslashIndex
        );
        if (extIndex > lastDirectorySeparatorIndex) {
            return path.substring(0, extIndex);
        }
        return path;
    }

public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    int separatorLength = FilenameUtils.EXTENSION_SEPARATOR_STR.length();
    String adjustedPath = path;
    int extensionPos = adjustedPath.lastIndexOf(FilenameUtils.EXTENSION_SEPARATOR);
    int baseNamePos = adjustedPath.lastIndexOf(FilenameUtils.DIRECTORY_SEPARATOR);
    int baseNamePos2 = adjustedPath.lastIndexOf(FilenameUtils.ALTERNATE_DIRECTORY_SEPARATOR);
    if (baseNamePos > extensionPos) {
        baseNamePos = baseNamePos2;
    }
    if ((extensionPos >= separatorLength - 1) && (baseNamePos < extensionPos)) {
        return adjustedPath.substring(0, extensionPos);
    } else {
        return adjustedPath;
    }
}

