private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(Collections.nCopies(n, 0));
    long totalSum = 0;

    for (int i = 0; i < n; i++) {
        totalSum += bounds.get(i);
    }

    suffixSum.set(n - 1, totalSum);
    for (int i = n - 2; i >= 0; i--) {
        suffixSum.set(i, suffixSum.get(i + 1) + bounds.get(i));
    }

    return new Pair<>(suffixSum, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(n);
    Long totalSum = 0L;
    for (int i = 0; i < n; i++) {
        totalSum += bounds.get(i);
    }
    long runningSum = totalSum;
    suffixSum.add((int) runningSum);
    for (int i = 1; i < n; i++) {
        runningSum -= bounds.get(i - 1);
        suffixSum.add((int) runningSum);
    }
    return new Pair<>(suffixSum, totalSum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;
    long currentSum = 0;

    // Compute suffix sum from right to left and accumulate total sum
    for (int i = bounds.size() - 1; i >= 0; i--) {
        int value = bounds.get(i);
        currentSum += value;
        suffixSum.add(0, (int) currentSum); // Prepend to maintain order
        totalSum += value;
    }

    // If the list was empty, we still return an empty list and zero sum
    if (bounds.isEmpty()) {
        return new Pair<>(new ArrayList<Integer>(), 0L);
    }

    return new Pair<>(suffixSum, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(Collections.nCopies(n, 0));

    long totalSum = 0;
    for (int num : bounds) {
        totalSum += num;
    }

    long runningSum = 0;
    // Iterate from the end to compute suffix sums
    for (int i = n - 1; i >= 0; i--) {
        runningSum += bounds.get(i);
        suffixSum.set(i, (int) runningSum);
    }

    return new Pair<>(suffixSum, totalSum);
}

