private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        return;
    }
    ListNode<E> head = list.head;
    if (head == null) {
        return;
    }
    // Detach all nodes from the source list
    ListNode<E> tail = list.tail;
    head.previous = null;
    tail.next = null;
    list.head = null;
    list.tail = null;
    list.size = 0;

    // Handle appending to the current list
    ListNode<E> currentTail = this.tail;
    if (currentTail == null) {
        // Current list is empty, adopt the moved nodes as is
        this.head = head;
        this.tail = tail;
    } else {
        // Append the moved nodes to the current list
        currentTail.next = head;
        head.previous = currentTail;
        this.tail = tail;
    }
    this.size += tail.next == null ? 0 : 0; // Size update logic below
    // Recalculate size or add 1 for each node? 
    // Actually, the prompt says "as if each node was removed ... and subsequently added".
    // removeListNode decrements list.size, addListNode increments this.size.
    // Since we moved all nodes, this.size should increase by the number of nodes moved.
    int count = 0;
    for (ListNode<E> node = head; node != null; node = node.next) {
        count++;
    }
    this.size += count;
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list.size() == 0) {
        return;
    }

    // Add all nodes from the provided list to this list
    ListNode<E> current = list.getHead().getNext();
    while (current != null) {
        // Temporarily store the next node to continue traversal
        ListNode<E> nextNode = current.getNext();

        // Move the current node to this list
        removeListNode(list, current);
        addListNode(current);

        // Move to the next node
        current = nextNode;
    }
}

