        }
        // Detach from source list
        firstNode.prev = null;
        lastNode.next = null;

        // Append to this list
        ListNode<E> thisLast = last;
        if (thisLast != null) {
            thisLast.next = firstNode;
        }
        firstNode.prev = thisLast;
        last = lastNode;
        size += list.size;
