public void abbreviate(final int nameStart, final StringBuffer buf) {
        int i = nameStart;
        while (i < name.length()) {
            if (name.charAt(i) == ' ') {
                i++;
            } else if (Character.isLetter(name.charAt(i))) {
                buf.append(Character.toUpperCase(name.charAt(i)));
                while (i < name.length() && Character.isLetter(name.charAt(i))) {
                    i++;
                }
            } else if (name.charAt(i) == '-' || name.charAt(i) == '\'') {
                buf.append(name.charAt(i));
                i++;
            } else {
                i++;
            }
        }
    }

public void abbreviate(final int nameStart, final StringBuffer buf) {
        // Get the length of the name starting at nameStart
        int nameLength = 0;
        for (int i = nameStart; i < name.length(); i++) {
            if (name.charAt(i) == ' ') break;
            nameLength++;
        }

        // If name length is 3 or less, append the first letter in uppercase
        if (nameLength <= 3) {
            buf.append(name.substring(nameStart, nameStart + nameLength).toUpperCase());
        } else {
            // If name length is greater than 3, append first and last letter in uppercase
            for (int i = nameStart; i < nameStart + nameLength; i++) {
                if (i == nameStart || i == nameStart + nameLength - 1) {
                    buf.append(name.charAt(i).toUpperCase());
                }
            }
        }
    }

public void abbreviate(final int nameStart, final StringBuffer buf) {
        buf.append(nameStart);
    }

public void abbreviate(final int nameStart, final StringBuffer buf) {
    int i = nameStart;
    // Skip any leading spaces
    while (i < this.length() && this.charAt(i) == ' ') {
        i++;
    }

    if (i >= this.length()) {
        return;
    }

    // Append first character (uppercase)
    char first = this.charAt(i);
    if (first != ' ') {
        buf.append(Character.toUpperCase(first));
        i++;
    }

    // Skip any whitespace after the first part
    while (i < this.length() && this.charAt(i) == ' ') {
        i++;
    }

    if (i >= this.length()) {
        return;
    }

    // Append the last name's first letter
    char last = this.charAt(i);
    buffer.append(Character.toUpperCase(last));
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (nameStart < 0 || nameStart >= fullName.length()) {
        return;
    }
    final char startChar = fullName.charAt(nameStart);
    if (Character.isLetter(startChar)) {
        buf.append(Character.toUpperCase(startChar));
        int i = nameStart + 1;
        boolean nextIsLetter = false;
        while (i < fullName.length()) {
            char c = fullName.charAt(i);
            if (Character.isLetter(c) && !nextIsLetter) {
                buf.append(Character.toUpperCase(c));
                nextIsLetter = true;
            } else if (!Character.isLetter(c)) {
                nextIsLetter = false;
            } else {
                nextIsLetter = false;
            }
            i++;
        }
    }
}

