private boolean pop(final String descriptor) {
        int offset = 0;
        while (offset < descriptor.length()) {
            char c = descriptor.charAt(offset);
            switch (c) {
                case 'V':
                case 'Z':
                case 'C':
                case 'B':
                case 'S':
                case 'I':
                    outputFrame.pop(0);
                    offset++;
                    break;
                case 'J':
                case 'F':
                    outputFrame.pop(1);
                    offset++;
                    break;
                case 'L':
                    int end = descriptor.indexOf(';', offset);
                    if (end < 0) {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    outputFrame.pop(ClassConstants.END_OF_INTERFACE_OBJECT);
                    offset = end + 1;
                    break;
                case '[':
                    outputFrame.pop(ClassConstants.REF_ARRAY);
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor character: " + c);
            }
        }
        return true;
    }

private void pop(final String descriptor){
    final AbstractType argumentType = AttributeUtils.parseStackTypeString(descriptor);
    final int size = getAbstractTypeSize(argumentType.getKind());
    for (int i = 0; i < size; i++) {
        outputFrame.pop();
    }
}

private void pop(final String descriptor) {
        int i = 0;
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == '[') {
                // array type, ignore for popping as it's just a wrapper
                i++;
                continue;
            }
            if (c == 'L') {
                // reference type, find the terminating semicolon
                int end = descriptor.indexOf(';', i);
                if (end == -1) {
                    break;
                }
                outputFrame.popType();
                i = end + 1;
            } else if (c == 'V' || c == 'B' || c == 'C' || c == 'D' || c == 'F' || c == 'I' || c == 'J' || c == 'S' || c == 'Z') {
                // primitive type
                outputFrame.popType();
                i++;
            } else {
                i++;
            }
        }
    }

private void pop(final String descriptor) {
    for (final String argType : descriptor.getArgumentTypes()) {
        outputFrame.pop(argType);
    }
}

private void pop(final String descriptor) {
    while (true) {
        if (descriptor == null || descriptor.isEmpty()) {
            return;
        }
        char first = descriptor.charAt(0);
        if (first == 'L') {
            int end = descriptor.indexOf(';');
            if (end < 0) {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            popAbstractType(descriptor.substring(1, end));
            descriptor = descriptor.substring(end + 1);
        } else if (first == '[') {
            popAbstractType(descriptor);
            int depth = 0;
            for (int i = 0; i < descriptor.length(); i++) {
                char c = descriptor.charAt(i);
                if (c == '[') {
                    depth++;
                } else if (c == ';' && depth > 0) {
                    descriptor = descriptor.substring(i + 1);
                    break;
                } else if (depth == 0 && c == 'L') {
                    int end = descriptor.indexOf(';', i);
                    if (end < 0) {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    descriptor = descriptor.substring(end + 1);
                    break;
                } else if (depth == 0 && c != '[') {
                    descriptor = descriptor.substring(1);
                    break;
                }
            }
        } else if (first == 'V') {
            return;
        } else {
            popPrimitive(first);
            descriptor = descriptor.substring(1);
        }
    }
}

