        return path;
    }

    // Normalize the separators to forward slashes
    path = path.replace('\\', '/');
    relativePath = relativePath.replace('\\', '/');

    StringBuilder result = new StringBuilder(path);

    // Ensure path ends with a separator if not empty and relativePath is not absolute
    if (result.length() > 0 && result.charAt(result.length() - 1) != '/' && !relativePath.startsWith("/")) {
        result.append('/');
    }

    // Remove leading '/' from relative path if present (since we're making it relative)
    if (relativePath.startsWith("/")) {
        // If relative path is absolute, just use it (but the problem says "relative to the full file path", so typically we strip leading slash)
        relativePath = relativePath.substring(1);
    }

    result.append(relativePath);

    // Normalize: resolve ".." and "." and multiple slashes
    String[] segments = result.toString().split("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    for (String segment : segments) {
        if (segment.equals(".") || segment.isEmpty()) {
            continue;
        } else if (segment.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
        } else {
            stack.push(segment);
        }
    }

    // Stack is in reverse order (last element is first), so reverse it
    java.util.List<String> parts = new java.util.ArrayList<>();
    while (!stack.isEmpty()) {
        parts.add(stack.pop());
    }

    if (parts.isEmpty()) {
        return "/";
    }

    // Check if original path started with "/" to preserve root
    boolean isAbsolute = path.startsWith("/");
    String joined = String.join("/", parts);
    if (isAbsolute) {
        return "/" + joined;
    } else {
        return joined;
    }
}

