        if (nextIndex >= depth) {
            throw new IllegalStateException("No next node.");
        }
        Node next = virtualStack.peek();
        if (next != null) {
            return new Edge(current, next);
        }
        return new Edge(current, nextChildren[nextIndex]);
    }

Edge edgeToNext() {
    if (currentNode == null) {
        throw new IllegalStateException("No current node available");
    }
    Node nextNode = nextNode();
    if (nextNode == null) {
        throw new IllegalStateException("No next node available");
    }
    Node realCurrent = getRealNode(currentNode);
    Node realNext = getRealNode(nextNode);
    Edge edge = getEdge(realCurrent, realNext);
    if (edge == null) {
        throw new IllegalStateException("No edge found between the current node and the next node");
    }
    return edge;
}

public Edge edgeToNext() {
    Edge edge = new Edge(currentNode, null);
    return edge;
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        return false;
    }
    int start = index;
    for (int i = 0; i < substring.length(); i++) {
        if (start >= str.length() || str.charAt(start) != substring.charAt(i)) {
            return false;
        }
        start++;
    }
    return true;
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (index < 0 || index >= str.length()) {
        return false;
    }
    int available = str.length() - index;
    if (substring.length() > available) {
        return false;
    }
    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
        if (str == null || substring == null) {
            return false;
        }

        int strLength = str.length();
        int substringLength = substring.length();

        // Check if the index + substringLength exceeds the string length
        if (index < 0 || index + substringLength > strLength) {
            return false;
        }

        for (int i = 0; i < substringLength; i++) {
            if (str.charAt(index + i) != substring.charAt(i)) {
                return false;
            }
        }

        return true;
    }

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    int len = substring.length();
    for (int i = 0; i < len; i++) {
        int thisIndex = index + i;
        if (thisIndex >= str.length()) {
            return false;
        }
        if (str.charAt(thisIndex) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        return false;
    }
    if (index < 0 || index >= str.length()) {
        return false;
    }
    if (substring.length() == 0) {
        return true;
    }
    if (index + substring.length() > str.length()) {
        return false;
    }
    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

protected void append(LoggingEvent event) {
    if (clientList == null || clientList.isEmpty()) {
        return;
    }
    for (Client client : clientList) {
        try {
            String message = layout.format(event);
            client.sendMessage(message);
        } catch (IOException e) {
            handleThrowable(e);
        }
    }
}

protected void append(LoggingEvent event) {
        String message = event.getFormattedMessage();

        if (clients != null && !clients.isEmpty()) {
            synchronized (clients) {
                for (Client client : clients) {
                    try {
                        client.sendLine(message);
                    } catch (Exception e) {
                        System.err.println("Error sending message to client: " + e.getMessage());
                    }
                }
            }
        }
    }

protected void append(LoggingEvent event) {
    String message = event.getMessage().toString();
    Instant timestamp = event.getTimeStamp().toInstant();
    Level level = event.getLevel();

    for (WebSocketSession session : sessions) {
        try {
            if (session.isOpen()) {
                String logEntry = String.format("[%s] [%s] %s", timestamp, level, message);
                session.sendMessage(new TextMessage(logEntry));
            }
        } catch (IOException e) {
            // Handle error, if needed, or log it
        }
    }
}

protected void append(LoggingEvent event) {
        if (event.getLevel().isGreaterOrEqual(LogLevel.TRACE)) {
            for (Appender appender : appenders) {
                appender.doAppend(event);
            }
        }
    }

protected void append(LoggingEvent event) {
        String message = event.getFormattedMessage();
        // Get the number of pattern converters (or specific format) if available
        // In a simpler telnet appender, we might just use the message and log name
        String logName = event.getLoggerName();
        Level level = event.getLevel();

        // Construct the message to send
        // A common format for telnet is [Level] LoggerName: Message
        String logMsg = "[" + level.toString() + "] " + logName + ": " + message;

        // Get the connected clients
        List<Socket> clients = clientConnections.keySet();

        // Write to each client
        for (Socket socket : clients) {
            try {
                PrintWriter writer = clientConnections.get(socket).getWriter();
                writer.println(logMsg);
                writer.flush();
            } catch (IOException e) {
                 // Handle IO exception, possibly remove the client if it's broken
                 // In a real implementation, we'd notify the error manager
                 // and remove the socket from the collection
            }
        }
    }

