private void checkIfPackedField() throws IOException {
        if (wireType == CodedInputFields.WIRETYPE_VARINT) {
            if (description.getRepeated()) {
                packedState = PackedState.PACKED;
            } else {
                packedState = PackedState.NOT_PACKED;
            }
        } else if (wireType == CodedInputFields.WIRETYPE_LENGTH_DELIMITED) {
            if (description.getRepeated()) {
                packedState = PackedState.PATCHED;
            } else {
                throw new InvalidProtocolBufferException("Field " + description.getName() + " is not a repeated field.");
            }
        } else {
            throw new InvalidProtocolBufferException("Field " + description.getName() + " has wrong wire type.");
        }
    }

private void checkIfPackedField() throws IOException {
    if (fieldType == FieldType.lengthDelimited && fieldState == FieldState.UNINITIALIZED) {
        int packedLength = WireFormat.getLengthField(input);
        int packedCount = packedLength / wireType;
        if (packedCount != packedLength / wireType) {
            throw new IOException("Invalid packed field length: " + packedLength);
        }
        packedCountLeft = packedCount;
        fieldState = FieldState.PACKED;
    }
}

