private void checkIfPackedField() throws IOException {
    if (!currentPackedField) {
        int readTag = input.readTag();
        if (readTag == WireFormat.computeTag(currentFieldNumber, WireFormat.FIXED64)) {
            // field is packed
            currentPackedField = true;
            packedField = readTag;
            packedTag = readTag;
            packedCount = 0;
            packedLimit = input.pushLimit();
        } else {
            // field is not packed
            currentPackedField = false;
        }
    }
}

private void checkIfPackedField() throws IOException {
        if (!isPackedFieldUsed) {
            if (fieldNumber == descriptor.getFields().length() || descriptor.isPacked(fieldNumber)) {
                isPackedFieldUsed = true;
                if (parsingPackedField) {
                    throw new IllegalStateException("Repeated field: " + fieldNumber + " encountered twice in packed form.");
                }
                parsingPackedField = true;
            }
        }
    }

public int readTag() throws IOException {
    int tag = readRawVarint32();
    if (tag == 0) {
        return 0;
    }
    // Verify that tag is not a negative value or an invalid group start/end
    int wireType = tag & PROTO_WIRETYPE_MASK;
    // While the protocol message parsers use this to read tags, since a protocol message may legally end wherever a tag occurs, and zero is not a valid tag number.
    // This method is designed to return 0 on EOF, but it also needs to handle the case where the tag is invalid.
    // In protobuf, a tag is a non-zero integer. If we read 0, it means EOF.
    return tag;
}

public int readTag() throws IOException {
    int tag = readRawVarint32();
    if (tag == 0) {
        return tag;
    } else if (WireFormat.isTagFieldNumber((tag) & 0x3F)) {
        return tag;
    } else {
        throw new InvalidProtocolBufferException(
            "Invalid tag: " + tag);
    }
}

public int readTag() throws IOException {
        int tag = readRawVarint32();
        if (tag == 0) {
            throw new CodedInputStream.InvalidTag();
        }
        return tag;
    }

public int readTag() throws IOException {
        int tag;
        do {
            tag = readRawVarint32();
            if (tag == 0) {
                return 0;
            }
        } while (wireTypeForTag(tag) == WIRETYPE_GROUP_END);
        return tag;
    }

public int readTag() throws IOException {
    int tag = readRawVarint32();
    return tag == 0 ? 0 : tag;
}

