private String buildContentRange() {
    if (totalSize == null || byteRangeStart == null || byteRangeEnd == null) {
        return null;
    }
    // According to RFC 7233, the partial content entity is always raw data
    // so the representation is the actual data, not a complete resource
    StringBuilder sb = new StringBuilder();

    if (byteRangeEnd != null) {
        sb.append("bytes ").append(byteRangeStart)
          .append('-').append(byteRangeEnd).append('/').append(totalSize);
    } else {
        // suffix-length format, e.g., bytes -100/1000 (means last 100 bytes)
        sb.append("bytes -").append(byteRangeStart).append('/').append(totalSize);
        // Wait, the suffix-length format is different. If it's a suffix-length range,
        // it's usually represented as "bytes -suffixLength/totalLength"
        // Actually, let's correct: For a suffix-length range, the representation is
        // "Content-Range: bytes <suffix-length>/total-size"
        // This is already done above.
    }

    return sb.toString();
}

private String buildContentRange() {
        // Assuming there are fields like 'from', 'to', and 'length' that are set in the context
        // For example, if the content range is from byte 0 to byte 99 out of 1000 total bytes
        Long from = this.from;
        Long to = this.to;
        Long length = this.length;

        if (length == null || length == -1) {
            // If length is unknown, omit the total length part
            return "bytes " + from + "-" + to;
        } else {
            // Include the total length
            return "bytes " + from + "-" + to + "/" + length;
        }
    }

private String buildContentRange() {
    if (contentLength == -1) {
        return "bytes */0";
    }
    return "bytes " + rangeStart + "-" + rangeEnd + "/" + contentLength;
}

private String buildContentRange() {
    if (resourceLength == 0) {
        return "bytes */0";
    }
    return "bytes " + (offset != null ? offset.toString() : "0") + "-" + (offset != null ? offset.add(length).subtract(BigInteger.ONE).toString() : resourceLength.subtract(BigInteger.ONE).toString()) + "/" + resourceLength.toString();
}

private String buildContentRange() {
    if (this.currentPos < 0 || this.totalSize < 0) {
        return null;
    }
    if (this.hasTotalSize) {
        return "bytes " + this.currentPos + "-" + (this.currentPos + this.chunkSize - 1) + "/" + this.totalSize;
    } else {
        return "bytes " + this.currentPos + "-" + (this.currentPos + this.chunkSize - 1) + "*/";
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> allSnapshots = new ArrayList<>();
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        allSnapshots.addAll(parseFromFileWithTimeRange(file, timeRange));
    }
    return allSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
        if (file == null || !file.exists() || !file.canRead()) {
            throw new IOException("File does not exist or is not readable: " + file);
        }
        List<ThreadSnapshot> snapshots = parseFromFile(file);
        if (timeRanges == null || timeRanges.isEmpty()) {
            return snapshots;
        }
        List<ThreadSnapshot> result = new ArrayList<>();
        for (ThreadSnapshot snapshot : snapshots) {
            long timestamp = snapshot.getTimestamp();
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (timestamp >= range.getStartTime() && timestamp <= range.getEndTime()) {
                    result.add(snapshot);
                    break;
                }
            }
        }
        return result;
    }

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        ThreadSnapshot currentSnapshot = null;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            if (line.startsWith("Full thread dump")) {
                currentSnapshot = new ThreadSnapshot();
            } else if (currentSnapshot != null) {
                currentSnapshot.appendLine(line);
            }
            if (line.startsWith("-")) {
                if (currentSnapshot != null) {
                    long timestamp = currentSnapshot.getTimestamp();
                    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                        if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                            threadSnapshots.add(currentSnapshot);
                            break;
                        }
                    }
                    currentSnapshot = null;
                }
            }
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            try {
                ThreadSnapshot snapshot = ThreadSnapshot.fromJson(line);
                if (isWithinTimeRange(snapshot.getTimestamp(), timeRanges)) {
                    threadSnapshots.add(snapshot);
                }
            } catch (Exception e) {
                // Skip invalid lines
            }
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
        List<ThreadSnapshot> allSnapshots = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            long lastSnapshotTime = -1;
            while ((line = reader.readLine()) != null) {
                if (line.trim().isEmpty()) {
                    continue;
                }
                ThreadSnapshot snapshot = ThreadSnapshot.parseLine(line);
                if (snapshot == null) {
                    continue;
                }
                if (lastSnapshotTime > 0 && snapshot.getTimestamp() != lastSnapshotTime) {
                    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                        if (timeRange.isInTimeRange(lastSnapshotTime)) {
                            allSnapshots.add(snapshot);
                            break;
                        }
                    }
                }
                lastSnapshotTime = snapshot.getTimestamp();
            }
        }
        return allSnapshots;
    }
